import std.string

test "mocked parse" {
    mock string.parseInt(s: String) -> Option<Int64> {
        return Some(12)
    }
    match string.parseInt("junk") {
        Some(n) => { assert(n == 12, "mocked") }
        None => { assert(false, "mocked") }
    }
}

test "restored" {
    match string.parseInt("34") {
        Some(n) => { assert(n == 34, "restored") }
        None => { assert(false, "restored") }
    }
}
